-- ============================================================================
-- COLORSHINE MES V2
-- 19_inventory_master_plant2000_test_load.sql
-- Source: InventoryMaster_MES.xlsx
-- Purpose: load the complete 983-row Plant 2000 inventory sample for MES testing.
-- The database columns preserve the exact business report fields/order exposed by the UI.
-- ============================================================================

ROLLBACK;
SET search_path TO mes, public;
BEGIN;

VALUES ('1.9.1','Plant 2000 InventoryMaster_MES test snapshot and exact report format')
ON CONFLICT (version_no) DO NOTHING;

CREATE TABLE IF NOT EXISTS mes.inventory_master (

    inventory_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source_row_no integer NOT NULL,
    source_file varchar(120) NOT NULL DEFAULT 'InventoryMaster_MES.xlsx',
    material_type varchar(20),
    stock_stage varchar(10),
    plant_code varchar(4) NOT NULL REFERENCES mes.plant_master(plant_code),
    storage_location varchar(10),
    material_code varchar(60),
    batch_no varchar(40) NOT NULL,
    batch_qty_mt numeric(14,4),
    qa_grade varchar(30),
    thickness_mm numeric(10,4),
    width_mm numeric(12,3),
    length_value numeric(14,3),
    temper varchar(40),
    coating varchar(40),
    jet_printing varchar(80),
    stock_generated_date date,
    stock_age_days integer,
    mes_po varchar(40),
    so_no varchar(20),
    so_line_item varchar(10),
    so_thickness_mm numeric(10,4),
    so_width_mm numeric(12,3),
    so_temper varchar(40),
    so_quality varchar(40),
    so_coating varchar(40),
    so_min_wt_mt numeric(14,4),
    so_max_wt_mt numeric(14,4),
    so_logo varchar(100),
    so_spangle varchar(100),
    so_jet_printing varchar(100),
    so_tll varchar(100),
    mother_rm_batch varchar(40),
    supplier_batch varchar(100),
    heat_no varchar(100),
    mother_stock_grn_date date,
    mother_stock_grn_age_days integer,
    rm_steel_grade varchar(50),
    carbon varchar(40),
    manganese varchar(40),
    sulphur varchar(40),
    phosphorus varchar(40),
    silicon varchar(40),
    aluminium varchar(40),
    carbon_equivalent varchar(40),
    nitrogen varchar(40),
    copper varchar(40),
    molybdenum varchar(40),
    chromium varchar(40),
    nickel varchar(40),
    rm_supplier varchar(200),
    imported_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ux_inventory_master_plant_batch UNIQUE (plant_code,batch_no)

);

CREATE INDEX IF NOT EXISTS ix_inventory_master_plant_stage
ON mes.inventory_master(plant_code,stock_stage,material_type);
CREATE INDEX IF NOT EXISTS ix_inventory_master_search
ON mes.inventory_master(plant_code,batch_no,material_code,storage_location);

-- Clean reload only the supplied Plant 2000 test snapshot.
DELETE FROM mes.inventory_master
WHERE plant_code='2000' AND source_file='InventoryMaster_MES.xlsx';


CREATE OR REPLACE VIEW mes.vw_inventory_master_report AS
SELECT * FROM mes.inventory_master;

COMMIT;

-- Verification: must show 983 rows and 14,979.908 MT for this source snapshot.
SELECT
  plant_code,
  count(*) AS inventory_rows,
  round(sum(batch_qty_mt),3) AS total_qty_mt,
  count(*) FILTER (WHERE stock_stage='RM') AS rm_rows,
  count(*) FILTER (WHERE stock_stage='WIP') AS wip_rows,
  count(*) FILTER (WHERE stock_stage='FG') AS fg_rows
FROM mes.inventory_master
WHERE plant_code='2000'
GROUP BY plant_code;

SELECT stock_stage, count(*) AS rows, round(sum(batch_qty_mt),3) AS qty_mt
FROM mes.inventory_master
WHERE plant_code='2000'
GROUP BY stock_stage
ORDER BY stock_stage;